package org.jsoup;

import java.io.*;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.net.URL;
import java.util.*;
import org.jsoup.helper.DataUtil;
import org.jsoup.helper.HttpConnection;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Entities;
import org.jsoup.parser.Parser;
import org.jsoup.safety.Cleaner;
import org.jsoup.safety.Whitelist;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Jsoup_isValid_TriageGen1Test {

    @Before
    public void setUp() {
        Entities.huge.init();
    }

    @Test
    public void testValidHtmlWithBasicEntities() {
        String html = "<p>hello &amp; goodbye</p>";
        assertTrue(Jsoup.isValid(html, Whitelist.basic()));
    }

    @Test
    public void testValidHtmlWithAllEntities() {
        String html = "<p>hello &amp; goodbye &#128512;</p>";
        assertTrue(Jsoup.isValid(html, Whitelist.basic()));
    }

    @Test
    public void testInvalidHtmlWithUntrustedEntities() {
        String html = "<p>hello &untrustedEntity;</p>";
        assertFalse(Jsoup.isValid(html, Whitelist.basic()));
    }

    @Test
    public void testValidHtmlWithAttributes() {
        String html = "<a href='https://example.com'>link</a>";
        assertTrue(Jsoup.isValid(html, Whitelist.relaxed()));
    }

    @Test
    public void testInvalidHtmlWithJavaScript() {
        String html = "<a href='javascript:alert(1)'>link</a>";
        assertFalse(Jsoup.isValid(html, Whitelist.relaxed()));
    }

    @Test
    public void testValidHtmlWithCustomWhitelist() {
        Whitelist whitelist = Whitelist.none().addTags("p", "a").addAttributes("a", "href");
        String html = "<p><a href='https://example.com'>link</a></p>";
        assertTrue(Jsoup.isValid(html, whitelist));
    }

    @Test
    public void testInvalidHtmlWithForbiddenTags() {
        Whitelist whitelist = Whitelist.none().addTags("p");
        String html = "<p><script>alert('test');</script></p>";
        assertFalse(Jsoup.isValid(html, whitelist));
    }

    @Test
    public void testEmptyHtml() {
        String html = "";
        assertTrue(Jsoup.isValid(html, Whitelist.basic()));
    }

    @Test
    public void testNullHtml() {
        String html = null;
        assertTrue(Jsoup.isValid(html, Whitelist.basic()));
    }

    @Test
    public void testHtmlWithInvalidEntities() {
        String html = "<p>hello &notAnEntity;</p>";
        assertFalse(Jsoup.isValid(html, Whitelist.basic()));
    }

    @Test
    public void testHtmlWithNestedTags() {
        String html = "<div><p>Nested tags</p></div>";
        assertTrue(Jsoup.isValid(html, Whitelist.basic()));
    }

    @Test
    public void testHtmlWithInvalidNestedTags() {
        String html = "<div><script>alert('test');</script></div>";
        assertFalse(Jsoup.isValid(html, Whitelist.basic()));
    }

    @Test
    public void testHtmlWithCustomParser() {
        String html = "<p>Custom parser test</p>";
        assertTrue(Jsoup.isValid(html, Whitelist.basic(), Parser.xmlParser()));
    }
}
